export function registerEditorTools(api,definitions){
 const context=document.modelContext;if(!context?.registerTool)return false;
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{/* Optional browser capability. */}};
 register({name:'read_process_diagram',title:'Read process diagram',description:'Read the current Tengwar diagram, including components, streams, documented properties and canvas settings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return api.getDiagram();}});
 register({name:'validate_process_structure',title:'Validate process structure',description:'Check the current diagram for connectivity, identification and documentation issues. This does not validate chemistry or GMP compliance.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return api.validate();}});
 register({name:'add_process_components',title:'Add process components',description:'Add a batch of process components to the visible diagram in Design mode. Coordinates specify each component centre.',inputSchema:{type:'object',properties:{components:{type:'array',minItems:1,maxItems:30,items:{type:'object',properties:{type:{type:'string',enum:Object.keys(definitions)},x:{type:'number',minimum:-50000,maximum:50000},y:{type:'number',minimum:-50000,maximum:50000}},required:['type','x','y'],additionalProperties:false}}},required:['components'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(api.getMode()!=='design')throw Error('Editing is locked in View mode.');if(!input||!Array.isArray(input.components)||input.components.length<1||input.components.length>30||Object.keys(input).some(k=>k!=='components'))throw Error('Expected 1–30 components.');for(const c of input.components){if(!c||!definitions[c.type]||!Number.isFinite(c.x)||!Number.isFinite(c.y)||Math.abs(c.x)>50000||Math.abs(c.y)>50000||Object.keys(c).some(k=>!['type','x','y'].includes(k)))throw Error('Invalid component definition or coordinates.');}if(api.getDiagram().nodes.length+input.components.length>1000)throw Error('Component limit exceeded.');input.components.forEach(c=>api.addComponent(c.type,{x:c.x,y:c.y}));return {added:input.components.length,componentCount:api.getDiagram().nodes.length};}});
 return true;
}
